-- Assert migration006 against persisted legacy rows before removing isolated fixtures.
select migration_test.ok((select count(*)=2 from public.leads where workspace_id='10000000-0000-0000-0000-000000000080'),'activities migration preserves both legacy lead rows');
select migration_test.ok(not exists(select 1 from migration_test.activities_original_leads o join public.leads l using(workspace_id,id) where to_jsonb(l)<>to_jsonb(o)),'activities migration preserves every lead field JSON timestamps owner and privacy exactly');
select migration_test.ok((select to_jsonb(w)=to_jsonb(o) from public.workspaces w join migration_test.activities_original_workspaces o using(id)),'activities migration preserves original company metadata');
select migration_test.ok((select to_jsonb(s)=to_jsonb(o) from public.workspace_settings s join migration_test.activities_original_settings o using(workspace_id)),'activities migration preserves presentation name goals and commission');
select migration_test.ok((select to_jsonb(m)=to_jsonb(o) from public.memberships m join migration_test.activities_original_memberships o using(workspace_id,user_id)),'activities migration preserves local member name role and activity state');
select migration_test.ok((select to_jsonb(s)=to_jsonb(o) from public.subscriptions s join migration_test.activities_original_subscriptions o using(workspace_id)),'activities migration preserves subscriptions without resetting trial or billing');
select migration_test.ok((select to_jsonb(p)=to_jsonb(o) from public.profiles p join migration_test.activities_original_profiles o using(id)),'activities migration preserves global account profile exactly');
select migration_test.ok((select to_jsonb(u)=to_jsonb(o) from auth.users u join migration_test.activities_original_auth o using(id)),'activities migration preserves Auth identity and all metadata exactly');
select migration_test.ok((select to_jsonb(r)=to_jsonb(o) from public.call_reviews r join migration_test.activities_original_reviews o using(workspace_id,lead_id)),'activities migration preserves existing leadership review exactly');
select migration_test.ok((select count(*)=(select count(*) from migration_test.activities_original_audit) from public.audit_logs where workspace_id='10000000-0000-0000-0000-000000000080'),'activities migration does not fabricate original administrative audits');
select migration_test.ok((select count(*)=2 from public.lead_events where workspace_id='10000000-0000-0000-0000-000000000080' and event_type='lead.created'),'activities migration backfills exactly one creation fact per existing lead');
select migration_test.ok(not exists(select 1 from public.lead_events e join migration_test.activities_original_leads l on l.workspace_id=e.workspace_id and l.id=e.lead_id where e.event_type='lead.created' and (e.created_at<>l.created_at or e.actor_id is distinct from l.created_by or e.metadata->'backfilled'<>'true'::jsonb)),'activities migration preserves creation timestamp and known or unknown original author');
select migration_test.ok((select count(*)=1 from public.lead_events where workspace_id='10000000-0000-0000-0000-000000000080' and event_type='call.snapshot'),'activities migration imports only the known legacy meeting');
select migration_test.ok((select metadata->'legacy'='true'::jsonb and actor_id is null and (metadata->'call'->>'callDate')::timestamptz='2026-09-12T12:00:00Z'::timestamptz and metadata->'call'->>'callScore'='8' from public.lead_events where workspace_id='10000000-0000-0000-0000-000000000080' and event_type='call.snapshot'),'activities migration labels snapshot legacy and normalizes its meeting date without inventing author');
select migration_test.ok((select metadata->'review'->>'feedback'='Feedback legado preservado' and metadata->'review'->>'score'='9' and metadata->'review'->>'reviewed_by'='00000000-0000-0000-0000-000000000080' and (metadata->'review'->>'reviewed_at')::timestamptz='2026-09-13T10:00:00Z'::timestamptz from public.lead_events where workspace_id='10000000-0000-0000-0000-000000000080' and event_type='call.snapshot'),'activities migration retains original leadership feedback score reviewer and timestamp');
select migration_test.ok((select e.created_at>=s.started_at and e.created_at<=clock_timestamp() from public.lead_events e cross join migration_test.activities_migration_started s where e.workspace_id='10000000-0000-0000-0000-000000000080' and e.event_type='call.snapshot'),'activities migration records legacy import time independently of original meeting time');
select migration_test.ok(not exists(select 1 from public.activities where workspace_id='10000000-0000-0000-0000-000000000080'),'activities migration never invents tasks from old notes or next-step text');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000080',false);
select migration_test.ok(public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-1')->>'call_count'='1','activities migration exposes one known legacy call instead of fabricated complete history');
select migration_test.ok(public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-1')->'items'->0->'legacy'='true'::jsonb and public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-1')->'items'->0->'leadership_review'->>'score'='9','activities migration history includes legacy marker and preserved review');
select migration_test.ok(public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-2')->>'call_count'='0','activities migration keeps historical lead without a call empty');
select migration_test.ok(jsonb_array_length(public.list_lead_events('10000000-0000-0000-0000-000000000080','activities-backfill-1')->'items')=1 and public.list_lead_events('10000000-0000-0000-0000-000000000080','activities-backfill-1')->'items'->0->>'event_type'='lead.created','activities migration hides technical legacy snapshot from commercial timeline');
select migration_test.ok(public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-1')->>'owner_name'='Nome local legado' and (public.list_lead_call_history('10000000-0000-0000-0000-000000000080','activities-backfill-1')->>'last_event_at')::timestamptz='2002-03-04T12:00:00Z'::timestamptz,'activities migration summary uses local owner name and excludes technical import time from last interaction');
select set_config('request.jwt.claim.sub','',false);
delete from public.workspaces where id='10000000-0000-0000-0000-000000000080';
delete from auth.users where id='00000000-0000-0000-0000-000000000080';
select migration_test.ok(not exists(select 1 from public.lead_events where workspace_id='10000000-0000-0000-0000-000000000080'),'activities migration fixture deletion cascades backfilled history and snapshots');
select migration_test.ok(not exists(select 1 from public.profiles where id='00000000-0000-0000-0000-000000000080'),'activities migration fixture deletion cascades profile after workspace cleanup');
